float hash(vec2 p) {
    float h = dot(p, vec2(127.1, 311.7));
    return fract(sin(h) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for(int i = 0; i < 8; i++) {
        f += amp * noise(p);
        p = rot * p * 2.1;
        amp *= 0.5;
    }
    return f;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    vec2 p = (2.0*fragCoord-iResolution.xy)/min(iResolution.x,iResolution.y);

    float breathingScale = 1.0 + sin(iTime * 0.2) * 0.1 + sin(iTime * 0.1) * 0.05;
    p *= breathingScale;

    p += vec2(
        sin(iTime * 0.1) * 0.15 + sin(iTime * 0.05) * 0.1,
        cos(iTime * 0.15) * 0.08 + cos(iTime * 0.07) * 0.05
    );

    vec3 color = vec3(0.02, 0.03, 0.1);

    float nebula1 = fbm(p + iTime * 0.05);
    float nebula2 = fbm(p * 1.5 - iTime * 0.03 + fbm(p * 0.5));
    float nebula3 = fbm(p * 0.5 + iTime * 0.07 + fbm(p));

    vec3 nebulaColor1 = mix(
        vec3(0.8, 0.2, 0.9),
        vec3(0.1, 0.5, 1.0),
        nebula1 * (1.0 + 0.2 * sin(iTime * 0.3))
    );

    vec3 nebulaColor2 = mix(
        vec3(1.0, 0.2, 0.5),
        vec3(0.2, 0.7, 1.0),
        nebula2 * (1.0 + 0.2 * cos(iTime * 0.2))
    );

    color += nebulaColor1 * 0.3 * smoothstep(0.2, 0.8, nebula1);
    color += nebulaColor2 * 0.25 * smoothstep(0.3, 0.7, nebula2);
    color += vec3(0.7, 0.3, 1.0) * 0.15 * smoothstep(0.4, 0.6, nebula3);

    color += pow(color, vec3(2.0)) * 1.0;
    color += pow(color, vec3(4.0)) * 0.5;

    float vignette = length(uv - 0.5);
    color *= smoothstep(1.2, 0.3, vignette);

    float aberration = 0.02 * vignette;
    vec3 colorShift = vec3(
        length(uv - 0.5 + aberration),
        length(uv - 0.5),
        length(uv - 0.5 - aberration)
    );
    color *= 1.0 - 0.1 * colorShift;

    fragColor = vec4(color, 1.0);
}
